using Aspire.Hosting.Testing;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evaluation;

/// <summary>
/// Evaluation harness that spins up the AppHost and runs scenario-based
/// evaluations against the agentic application.
/// </summary>
public class EvaluationHarness : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder _builder = default!;
    private DistributedApplication _app = default!;

    public async Task InitializeAsync()
    {
        _builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _builder.BuildAsync();
        await _app.StartAsync();
    }

    public async Task DisposeAsync()
    {
        await _app.DisposeAsync();
    }

    [Fact]
    public async Task AppHost_Starts_Successfully()
    {
        // Verify the distributed application started without errors.
        await _app.WaitForResourcesToStartAsync();
    }
}

using System.Diagnostics;
using YamlDotNet.Serialization;
using YamlDotNet.Serialization.NamingConventions;
using Xunit;
using Xunit.Abstractions;

namespace MyApp.Evaluation;

/// <summary>
/// Loads evaluation scenarios from evaluation.yml and runs each one,
/// asserting the expected outcome criteria are met.
/// </summary>
public class ScenarioRunner
{
    private readonly ITestOutputHelper _output;

    public ScenarioRunner(ITestOutputHelper output)
    {
        _output = output;
    }

    [Fact]
    public void Scenarios_FileExists()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "evaluation.yml");
        Assert.True(File.Exists(path), $"evaluation.yml not found at {path}");
    }

    [Fact]
    public void Scenarios_ParseSuccessfully()
    {
        var config = LoadConfig();
        Assert.NotNull(config);
        Assert.NotEmpty(config.Scenarios);

        foreach (var scenario in config.Scenarios)
        {
            _output.WriteLine($"Loaded scenario: {scenario.Name} - {scenario.Description}");
            Assert.False(string.IsNullOrWhiteSpace(scenario.Name));
            Assert.NotNull(scenario.Expected);
        }
    }

    [Fact]
    public void Scenarios_HaveValidLatencyThresholds()
    {
        var config = LoadConfig();

        foreach (var scenario in config.Scenarios)
        {
            if (scenario.Expected.MaxLatencyMs.HasValue)
            {
                Assert.True(scenario.Expected.MaxLatencyMs.Value > 0,
                    $"Scenario '{scenario.Name}' has invalid max_latency_ms");
            }
        }
    }

    private static EvaluationConfig LoadConfig()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "evaluation.yml");
        var yaml = File.ReadAllText(path);
        var deserializer = new DeserializerBuilder()
            .WithNamingConvention(UnderscoredNamingConvention.Instance)
            .Build();
        return deserializer.Deserialize<EvaluationConfig>(yaml);
    }
}

public class EvaluationConfig
{
    public List<Scenario> Scenarios { get; set; } = new();
}

public class Scenario
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Input { get; set; } = string.Empty;
    public ExpectedOutcome Expected { get; set; } = new();
}

public class ExpectedOutcome
{
    public List<string>? Contains { get; set; }
    public List<string>? DoesNotContain { get; set; }
    public int? MaxLatencyMs { get; set; }
}

